def mumu_capture_matches(adb_image,sdk_image):
    if adb_image.size!=sdk_image.size:return False
    left=np.asarray(adb_image.resize((80,45)).convert('RGB'),dtype=np.int16)
    right=np.asarray(sdk_image.resize((80,45)).convert('RGB'),dtype=np.int16)
    if float(left.std(axis=(0,1)).mean())<5 or float(right.std(axis=(0,1)).mean())<5:return False
    difference=np.abs(left-right).mean(axis=2)
    return float(difference.mean())<18 and float((difference<35).mean())>.85
def background_capture_settings(settings,**overrides):
    values=dict(settings or {},**overrides)
    values.update(background_connection_profile='fast',background_capture_preference='auto',
background_input_preference='auto',background_mumu_enhanced=True,
background_capture_mode='mumu_enhanced',background_input_backend='mumu_sdk',
background_skill_input_backend='controller',background_transport_auto=False)
    values.pop('background_probe_input',None)
    values['background_adb_raw_capture']=True
    values['background_touch_mode']='scrcpy'
