    def _foreground_package(self):
        text=self._shell(['dumpsys','window','windows'],timeout=5)
        match=re.search(r'mCurrentFocus=.*?\b([A-Za-z][A-Za-z0-9_.]+)/(?:[A-Za-z0-9_.$]+)',text)
        if not match:
            text=self._shell(['dumpsys','activity','activities'],timeout=5)
