def farming_connection_key(executable,settings):
    fields=('background_adb_serial','background_mumu_root','background_mumu_index',
'background_connection_profile','background_capture_mode','background_input_backend','background_skill_input_backend','background_maa_sample_ms','background_maa_corner_ms','background_sdk_sample_ms','background_sdk_corner_ms')
