        proof=lifted_colour_texture(before_frame,current_frame,(x,y,w,h),index,index,expected_code,classify_cell,_curved_spike_overlay,background=True)
        if proof is not None:
            stable=_touch_start_stable_board(before_frame,current_frame,(x,y,w,h),index)
