def sdk_displaced_start(before,current,rect,board,wanted):
    """Diagnose another actually lifted cell, never authorize its movement."""
    x,y,w,h=rect;cw,ch=w/6,h/5;candidates=[]
    for cell in range(30):
        if cell==wanted:continue
        cx=x+(cell%6+.5)*cw;cy=y+(cell//6+.5)*ch
        box=(round(cx-.3*cw),round(cy-.4*ch),round(cx+.3*cw),round(cy+.3*ch))
        a=np.asarray(before.crop(box),dtype=np.int16);b=np.asarray(current.crop(box),dtype=np.int16)
        change=float(np.abs(a-b).mean())
        if change>12:candidates.append((change,cell))
    for _,cell in sorted(candidates,reverse=True)[:4]:
        check=sdk_start_hold_verification(before,current,rect,cell,board[cell])
        if check.get('confirmed'):
            return dict(reason='different_start_cell_lifted',expected_start_cell=wanted,observed_start_cell=cell)
    return dict(expected_start_cell=wanted,observed_start_cell=None)
