        self.reward_candidate_count = 0
        self.reward_processed_this_visit = False
        self.reward_no_header_count = 0
        self.reward_last_scan_debug = "크리스탈 획득 화면 자동 감지를 기다리는 중입니다."
        self.board_history = []
