    def _configure_visual_model(self):
        import base64
        self._legacy_ai_cleanup_errors=ai_core.purge_local_ai_data(self.data_paths['root'])
        for key in list(self.user_settings):
            if key.startswith('ai_') or key in ('visual_ai_enabled','background_status_templates'):
                self.user_settings.pop(key,None)
        if self.data_paths.get('settings'):
            _atomic_json_write(self.data_paths['settings'],self.user_settings)
        ai_core.VISUAL_AI_MODEL=visual_model_load(base64.b85decode(VISUAL_MODEL_B85))
        self._visual_model_load_error=''
        return self._visual_model_status_text()
    def _visual_model_status_text(self):
        model=ai_core.VISUAL_AI_MODEL
        text='개발환경 학습 모델 · '+(model['metadata']['id'] if model else '내장 판독')+' · 사용자 학습·자료 저장 없음'
        if getattr(self,'_legacy_ai_cleanup_errors',[]):text+=' · 이전 AI 자료 삭제 실패: '+', '.join(row['name'] for row in self._legacy_ai_cleanup_errors)
        return text
    def _update_visual_model_status(self,message=None):
        variable=getattr(self,'_visual_model_status_var',None)
        if variable is not None:
            try:variable.set(message or self._visual_model_status_text())
            except tk.TclError:pass
    def train_visual_model(self):
        self._update_visual_model_status('개발환경 학습 모델만 사용합니다. 로컬 학습·모델 저장 기능은 제거됐습니다.')
