    def _creation_navigation_anchor(self,frame,kind):
        """Verify the user's scroll or purple-plus control before tapping."""
        import cv2
        if frame.size!=(1600,940):return None
        rgb=np.asarray(frame.convert('RGB')).astype('int16')
        if kind=='scroll':mask=(rgb[...,0]>150)&(rgb[...,0]>rgb[...,1]*1.35)&(rgb[...,0]>rgb[...,2]*1.25)
        elif kind=='plus':mask=(rgb[...,2]>120)&(rgb[...,0]>70)&(rgb[...,2]>rgb[...,1]*1.5)&(rgb[...,0]>rgb[...,1]*1.2)
        else:return None
        _,_,stats,_=cv2.connectedComponentsWithStats(mask.astype('uint8'),8)
        points=[]
        for x,y,w,h,area in stats[1:]:
            if kind=='scroll':
                if not (600<x+w/2<1000 and 40<y+h/2<260 and 60<w<280 and 60<h<280 and .65<w/h<1.5 and area>.22*w*h):continue
                patch=rgb[y:y+h,x:x+w];gold=(patch[...,0]>130)&(patch[...,1]>90)&(patch[...,2]<180)&(patch[...,0]>patch[...,2]*1.1)
                if gold[:h//2].sum()<50:continue
            else:
                if not (x>1250 and 130<y<800 and 60<w<250 and 30<h<140 and 1.3<w/h<4 and area>.35*w*h):continue
                patch=rgb[y:y+h,x:x+w];white=(patch.min(2)>220).astype('uint8')
                _,_,glyphs,centers=cv2.connectedComponentsWithStats(white,8);found=False
                for index,(gx,gy,gw,gh,ga) in enumerate(glyphs[1:],1):
                    if not (10<gw<70 and 10<gh<70 and .7<gw/gh<1.4 and .25*w<centers[index][0]<.70*w and .2*h<centers[index][1]<.8*h):continue
                    ink=white[gy:gy+gh,gx:gx+gw]
                    if .15<ga/(gw*gh)<.75 and ink[gh//2].mean()>.7 and ink[:,gw//2].mean()>.7:found=True
                if not found:continue
            points.append((x+w/2,y+h/2))
        return points[0] if len(points)==1 else None
    def _farming_owner_search_names(self,group):
        """Unconfirmed OCR text is a search hint only; never an identity mapping."""
        if group.get('owner_name_confirmed') is not False:return [group['name']]
        reads=group.get('owner_observation',{}).get('title',{}).get('direct_readings',[])
        names=[]
        for row in reads:
            text=str(row.get('text','')).strip()
            if row.get('score',0)>=.85 and re.search('[가-힣]',text) and text not in names:names.append(text)
        return names or [str(group['owner_number'])]
    def _search_line_confirmed(self,frame,text,box,tokens):
        x0,y0,x1,y1=box;wanted=crystal_name_key(text)
        line=[t for t in tokens if t.score>=.90 and y0<=t.cy<=y1 and x0<=t.cx<=x1]
        evidence=dict(readings=[],tokens=[dict(text=t.text,score=float(t.score)) for t in line])
        if any(crystal_name_key(t.text)==wanted for t in line):return True,evidence
        if line and crystal_name_key(' '.join(t.text for t in sorted(line,key=lambda t:t.x1)))==wanted:return True,evidence
        _,views=background_heading_views(frame.crop(box))
        reads=[self._recognize_title_line(view) for view in views]
        evidence['readings']=[(value,float(score)) for value,score in reads]
        return len(reads)==2 and all(score>=.90 and crystal_name_key(value)==wanted for value,score in reads),evidence
