    def _creation_search_field(self,frame,tokens):
        """Recognize a visible placeholder; never tap an assumed search position."""
        fields=[t for t in tokens if t.score>=.9 and _compact_ocr_text(t.text) in ('이름/스킬','이름스킬') and t.cy<300]
