        if frame.size!=(1600,940):return None
        import cv2
        rgb=np.asarray(frame.crop((0,0,1600,300)).convert('RGB'),dtype=np.int16)
        pale=((rgb.min(2)>=205)&(rgb.max(2)<=245)&(np.ptp(rgb,axis=2)<20)).astype('uint8')
        _,_,stats,_=cv2.connectedComponentsWithStats(pale,8);found=[]
