if __name__ == "__main__":
    __import__('multiprocessing').freeze_support()
    if __import__("sys").platform != "win32":
        print("이 시험판은 Windows 전용입니다.")
    if sys.platform == 'win32' and globals().get('_PAD0_INSTALL_PAYLOAD'):
        try:
            from pad0_install import apply_embedded_layout
            apply_embedded_layout(Path(__file__), _PAD0_INSTALL_PAYLOAD)
        except (OSError, ValueError, KeyError, TypeError) as error:
            print(f'Portable layout update incomplete ({type(error).__name__}); program retained.', flush=True)
    App().run()
